CARDIO.register({"item":"d155","meta":{"num":"d155","label":"155","spe":"dermato","short":"Bactéries et mycoses","title":"Infections cutanéo-muqueuses bactériennes et mycosiques","section":"D","chapter":8,"pages":"144-176","sdd":[{"num":37,"label":"Éruptions chez l'enfant"},{"num":80,"label":"Alopécie et chute des cheveux"},{"num":81,"label":"Anomalie des ongles"},{"num":85,"label":"Érythème"},{"num":91,"label":"Anomalie des muqueuses"},{"num":151,"label":"Œdème de la face et du cou"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":310,"label":"Prévention chez un malade contagieux"}]},"objectives":[{"id":"d155-obj-01","rank":"A","rubric":"Définition","title":"Savoir définir une mycose superficielle","desc":""},{"id":"d155-obj-02","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes d'une infection candidosique et des mycoses (candidoses incluses)","desc":"orale, génitale, unguéale, d'un pli"},{"id":"d155-obj-03","rank":"A","rubric":"Éléments physiopathologiques","title":"Connaître les facteurs favorisants des infections cutanéo-muqueuses à Candida et mycoses","desc":""},{"id":"d155-obj-04","rank":"A","rubric":"Contenu multimédia","title":"Photographies d'un exemple typique de ces mycoses","desc":"Ces images doivent être les plus classiques"},{"id":"d155-obj-05","rank":"B","rubric":"Examens complémentaires","title":"Connaître les indications du prélèvement mycologique de la peau et des phanères","desc":"Prélèvement en laboratoire pour les dermatophytes"},{"id":"d155-obj-06","rank":"B","rubric":"Prise en charge","title":"Connaître les principes du traitement des mycoses (candidoses incluses)","desc":""},{"id":"d155-obj-07","rank":"A","rubric":"Définition","title":"Connaître la définition d'un panaris","desc":""},{"id":"d155-obj-08","rank":"A","rubric":"Définition","title":"Connaître la définition d'un abcès","desc":""},{"id":"d155-obj-09","rank":"B","rubric":"Prise en charge","title":"Connaître les principes du traitement d'un abcès","desc":""},{"id":"d155-obj-10","rank":"B","rubric":"Prise en charge","title":"Connaître les principes du traitement d'un panaris","desc":""},{"id":"d155-obj-11","rank":"A","rubric":"Éléments physiopathologiques","title":"Connaître la définition et la physiopathologie de l'anthrax et du furoncle","desc":""},{"id":"d155-obj-12","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques du furoncle","desc":""},{"id":"d155-obj-13","rank":"A","rubric":"Contenu multimédia","title":"Photographie de furoncle","desc":""},{"id":"d155-obj-14","rank":"B","rubric":"Suivi et/ou pronostic","title":"Connaître les principes du traitement du furoncle","desc":""},{"id":"d155-obj-15","rank":"B","rubric":"Suivi et/ou pronostic","title":"Connaître les complications du furoncle","desc":""},{"id":"d155-obj-16","rank":"B","rubric":"Suivi et/ou pronostic","title":"Furonculose (facteurs favorisants, examens à réaliser)","desc":""},{"id":"d155-obj-17","rank":"A","rubric":"Définition","title":"Impétigo : définition (physiopathologie, épidémiologie, impétiginisation)","desc":""},{"id":"d155-obj-18","rank":"A","rubric":"Diagnostic positif","title":"Impétigo : diagnostic (impétigo croûteux, impétigo bulleux, impétiginisation)","desc":""},{"id":"d155-obj-19","rank":"A","rubric":"Contenu multimédia","title":"Impétigo : contenu multimédia (impétigo croûteux, impétigo bulleux, impétiginisation)","desc":""},{"id":"d155-obj-20","rank":"B","rubric":"Prise en charge","title":"Impétigo : connaître les principes du traitement (adulte et enfant), antibiothérapie et mesures complémentaires","desc":""},{"id":"d155-obj-21","rank":"B","rubric":"Suivi et/ou pronostic","title":"Diagnostiquer les complications d'un impétigo","desc":""},{"id":"d155-obj-22","rank":"A","rubric":"Définition","title":"Connaître la définition et la physiopathologie de la folliculite","desc":""},{"id":"d155-obj-23","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques de la folliculite","desc":""},{"id":"d155-obj-24","rank":"A","rubric":"Contenu multimédia","title":"Photographie de folliculite","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"d155-qroc-001","type":"QROC","rank":"A","objective":"d155-obj-17","tags":["étiologie"],"difficulty":1,"question":"Quel est le principal germe responsable de l'impétigo en France (environ 90 % des cas) ?","answer":"Staphylococcus aureus","accept":["S. aureus","staphylocoque doré","staphylocoque aureus","staphylocoque"],"keywords":["staph"],"explanation":"En France, S. aureus est en cause dans environ 90 % des impétigos. Streptococcus pyogenes domine surtout dans les pays émergents, et les deux germes peuvent être associés.","src":"p. 147"},{"id":"d155-qroc-002","type":"QROC","rank":"A","objective":"d155-obj-19","tags":["clinique"],"difficulty":1,"question":"Comment qualifie-t-on les croûtes de l'impétigo, dont l'aspect évoque du miel cristallisé ?","answer":"Mélicériques","accept":["mélicérique","croûte mélicérique"],"keywords":["mélicér"],"explanation":"La vésicule ou la bulle fragile se rompt et laisse une érosion recouverte d'une croûte mélicérique ; en se regroupant, les lésions peuvent former des placards polycycliques à contours circinés.","src":"p. 147"},{"id":"d155-qroc-003","type":"QROC","rank":"A","objective":"d155-obj-18","tags":["clinique","pédiatrie"],"difficulty":1,"question":"Quelle est la localisation classique de l'impétigo chez l'enfant ?","answer":"Le pourtour de la bouche","accept":["pourtour de la bouche","péribuccale","péribuccal","autour de la bouche","pourtour buccal"],"keywords":["bouche"],"explanation":"Toutes les zones cutanées peuvent être touchées, mais le pourtour de la bouche est classique chez l'enfant ; l'état général est conservé, sans fièvre, avec parfois une adénopathie satellite.","src":"p. 147"},{"id":"d155-qroc-004","type":"QROC","rank":"A","objective":"d155-obj-18","tags":["physiopathologie"],"difficulty":2,"question":"Dans l'impétigo bulleux, quelle protéine du desmosome de l'épiderme superficiel est la cible des exfoliatines de S. aureus ?","answer":"La desmogléine 1","accept":["desmogléine 1","desmogléine","DSG1"],"keywords":["desmogl"],"explanation":"Les exfoliatines A et B, produites localement par S. aureus, ciblent la desmogléine 1 des desmosomes de l'épiderme superficiel, ce qui provoque un décollement superficiel.","src":"p. 148"},{"id":"d155-qroc-005","type":"QROC","rank":"A","objective":"d155-obj-17","tags":["étiologie"],"difficulty":1,"question":"Comment nomme-t-on la surinfection bactérienne d'une dermatose préexistante (eczéma, varicelle) ou de lésions de grattage (gale, pédiculose), forme la plus fréquente d'impétigo chez l'adulte ?","answer":"L'impétiginisation","accept":["impétiginisation","impétiginisé","impétiginisée"],"keywords":["impétigin"],"explanation":"Chez l'adulte, l'impétigo est rarement primitif : il s'agit le plus souvent d'une impétiginisation d'une dermatose sous-jacente ou de lésions de grattage.","src":"p. 148"},{"id":"d155-qroc-006","type":"QROC","rank":"A","objective":"d155-obj-18","tags":["diagnostic"],"difficulty":2,"question":"Quels seuils chiffrés (surface cutanée atteinte, nombre de lésions) définissent un impétigo grave justifiant un prélèvement bactériologique ?","answer":"Surface > 2 % et plus de 6 lésions","accept":["> 2 % et > 6 lésions","plus de 2 % et plus de 6 lésions"],"keywords":["2","6"],"explanation":"Un impétigo localisé ou peu étendu ne se prélève pas. Le prélèvement est indiqué dans les formes graves : ecthyma, atteinte de plus de 2 % de la surface cutanée, plus de 6 lésions ou extension rapide.","src":"p. 147"},{"id":"d155-qroc-007","type":"QROC","rank":"B","objective":"d155-obj-20","tags":["traitement"],"difficulty":1,"question":"Quel antibiotique local est utilisé dans l'impétigo localisé ou peu étendu (2 à 3 fois par jour pendant 5 jours) ?","answer":"La mupirocine","accept":["mupirocine"],"keywords":["mupirocine"],"explanation":"La prise en charge associe des soins de toilette à l'eau et au savon, sans antiseptique local, et la mupirocine locale 2 à 3 fois par jour pendant 5 jours.","src":"p. 149"},{"id":"d155-qroc-008","type":"QROC","rank":"A","objective":"d155-obj-24","tags":["clinique"],"difficulty":1,"question":"Quelle est la lésion élémentaire d'une folliculite superficielle ?","answer":"Une pustule centrée par un poil","accept":["pustule centrée par un poil","papulo-pustule centrée par un poil","pustule folliculaire"],"keywords":["pustule","poil"],"explanation":"La folliculite superficielle est une infection de l'ostium du follicule pilo-sébacé, le plus souvent due à S. aureus : pustule centrée par un poil avec érythème périfolliculaire, en nombre variable sur les régions pileuses.","src":"p. 150"},{"id":"d155-qroc-009","type":"QROC","rank":"A","objective":"d155-obj-22","tags":["définition"],"difficulty":1,"question":"Quelle structure cutanée est infectée, le plus souvent par S. aureus, au cours d'une folliculite superficielle ?","answer":"Le follicule pilo-sébacé (ostium folliculaire)","accept":["follicule pilo-sébacé","ostium folliculaire","ostium"],"keywords":["follicule"],"explanation":"La folliculite superficielle est une infection de l'ostium du follicule pilo-sébacé, le plus souvent due à Staphylococcus aureus ; le furoncle est l'infection profonde et nécrosante de ce même follicule.","src":"p. 150"},{"id":"d155-qroc-010","type":"QROC","rank":"A","objective":"d155-obj-11","tags":["définition"],"difficulty":1,"question":"Comment définit-on un furoncle ?","answer":"Infection profonde et nécrosante du follicule pilo-sébacé","accept":["infection nécrosante profonde du follicule pilo-sébacé","infection profonde du follicule pilo-sébacé"],"keywords":["profond","nécros","follicule"],"explanation":"Le furoncle est une infection profonde et nécrosante du follicule pilo-sébacé due à Staphylococcus aureus, alors que la folliculite superficielle n'atteint que l'ostium folliculaire.","src":"p. 150"},{"id":"d155-qroc-011","type":"QROC","rank":"A","objective":"d155-obj-11","tags":["définition"],"difficulty":1,"question":"Comment appelle-t-on un conglomérat de plusieurs furoncles ?","answer":"Un anthrax","accept":["anthrax"],"keywords":["anthrax"],"explanation":"L'anthrax est un conglomérat de plusieurs furoncles ; il fait partie des complications du furoncle, avec la multiplication des lésions, la dermohypodermite périlésionnelle et l'abcédation secondaire.","src":"p. 151"},{"id":"d155-qroc-012","type":"QROC","rank":"A","objective":"d155-obj-13","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on le follicule pileux nécrosé éliminé à la phase d'état d'un furoncle ?","answer":"Le bourbillon","accept":["bourbillon"],"keywords":["bourbillon"],"explanation":"Le furoncle est une lésion papulo-nodulaire très inflammatoire qui évolue en 5 à 10 jours vers la nécrose folliculaire, avec élimination du follicule sous la forme d'un bourbillon jaunâtre.","src":"p. 150-151"},{"id":"d155-qroc-013","type":"QROC","rank":"B","objective":"d155-obj-14","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle antibiothérapie recommande-t-on pour un furoncle isolé, non compliqué ?","answer":"Aucune (ni locale ni générale)","accept":["aucune","pas d'antibiothérapie","pas d'antibiotique","aucun antibiotique"],"keywords":["aucun"],"explanation":"Le furoncle isolé se traite localement : pas de manipulation, toilette quotidienne à l'eau et au savon, lavage des mains, incision de l'extrémité pour évacuer le bourbillon et pansement. L'antibiothérapie orale de 5 jours (clindamycine ou pristinamycine) est réservée aux furoncles compliqués.","src":"p. 152"},{"id":"d155-qroc-014","type":"QROC","rank":"A","objective":"d155-obj-15","tags":["urgence"],"difficulty":2,"question":"Après avoir manipulé un furoncle de l'aile du nez, un patient présente de la fièvre, un œdème du visage et un cordon veineux induré. Quelle complication grave évoquer en urgence ?","answer":"Staphylococcie maligne de la face","accept":["staphylococcie maligne","staph maligne de la face"],"keywords":["staph","maligne"],"explanation":"Cette complication grave mais exceptionnelle fait suite à la manipulation intempestive d'un furoncle de la zone délimitée par le canthus interne, la commissure labiale et l'aile du nez.","src":"p. 151"},{"id":"d155-qroc-015","type":"QROC","rank":"A","objective":"d155-obj-15","tags":["complications","urgence"],"difficulty":2,"question":"Quelle complication engageant le pronostic vital peut survenir au cours d'une staphylococcie maligne de la face ?","answer":"Thrombophlébite du sinus caverneux","accept":["thrombophlébite du sinus caverneux","thrombose du sinus caverneux","sinus caverneux"],"keywords":["sinus caverneux"],"explanation":"Le mécanisme est une thrombophlébite superficielle septique ; la complication majeure, qui engage le pronostic vital, est la thrombophlébite du sinus caverneux.","src":"p. 151-152"},{"id":"d155-qroc-016","type":"QROC","rank":"A","objective":"d155-obj-07","tags":["définition"],"difficulty":1,"question":"Comment définit-on un panaris ?","answer":"Une infection du repli unguéal","accept":["infection du repli unguéal","repli unguéal infecté"],"keywords":["repli"],"explanation":"Le panaris est une infection du repli unguéal, érythémateux, œdémateux et douloureux.","src":"p. 152"},{"id":"d155-qroc-017","type":"QROC","rank":"B","objective":"d155-obj-10","tags":["traitement"],"difficulty":2,"question":"Quel geste est indiqué devant un panaris compliqué d'une collection purulente ?","answer":"Une incision avec drainage","accept":["incision et drainage","incision-drainage","incision drainage"],"keywords":["incision","drainage"],"explanation":"Le panaris se traite par des antiseptiques locaux ; une antibiothérapie antistaphylococcique orale n'est ajoutée qu'en cas de résistance ou de complication, et l'incision avec drainage est réservée à la collection purulente.","src":"p. 152"},{"id":"d155-qroc-018","type":"QROC","rank":"A","objective":"d155-obj-08","tags":["définition"],"difficulty":1,"question":"Comment définit-on un abcès des parties molles ?","answer":"Une collection de pus","accept":["collection de pus","collection purulente","poche de pus"],"keywords":["collection"],"explanation":"L'abcès est une collection de pus, mode de résolution physiologique mais imparfait d'une infection locale : plaque ou nodule érythémateux très douloureux, qui devient fluctuant en quelques jours.","src":"p. 153"},{"id":"d155-qroc-019","type":"QROC","rank":"A","objective":"d155-obj-03","tags":["physiopathologie"],"difficulty":1,"question":"Chez l'être humain, quels sont les sites où Candida albicans vit normalement en saprophyte ?","answer":"Tube digestif et muqueuses génitales","accept":["tube digestif et muqueuses génitales féminines","muqueuses digestive et génitale","digestif et génital"],"keywords":["digestif","génital"],"explanation":"Candida albicans est un endosaprophyte des muqueuses (tube digestif, muqueuses génitales féminines) et un pathogène d'opportunité ; il n'est jamais présent sur la peau saine.","src":"p. 155"},{"id":"d155-qroc-020","type":"QROC","rank":"A","objective":"d155-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Que traduit l'isolement de Candida albicans à partir d'une lésion cutanée ?","answer":"Il est toujours pathogène : candidose cutanée","accept":["toujours pathogène","candidose cutanée"],"keywords":["pathogène"],"explanation":"C. albicans est toujours pathogène lorsqu'il est isolé d'une lésion cutanée. Sur une muqueuse digestive ou génitale, il peut n'être qu'un saprophyte : l'interprétation tient alors compte du nombre de colonies et de la présence de filaments.","src":"p. 166"},{"id":"d155-qroc-021","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on l'intertrigo de la commissure labiale d'une candidose buccale (fond du pli érythémateux, fissuraire, parfois macéré) ?","answer":"La perlèche","accept":["perlèche","perlèche candidosique"],"keywords":["perlèche"],"explanation":"La perlèche est uni- ou bilatérale et peut s'étendre à la peau adjacente et au reste de la lèvre (chéilite). Les quatre formes de candidose buccale sont la perlèche, la glossite, la stomatite et le muguet.","src":"p. 156"},{"id":"d155-qroc-022","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":1,"question":"Quel est l'aspect de la langue dans une glossite candidosique ?","answer":"Rouge et dépapillée","accept":["langue rouge et dépapillée","dépapillée","rouge et lisse","lisse et rouge","érythémateuse et lisse"],"keywords":["dépapill"],"explanation":"La glossite candidosique réalise une langue rouge, lisse et dépapillée, souvent associée à une stomatite (sécheresse buccale, sensation cuisante, dysgueusie, muqueuse rouge, brillante et douloureuse).","src":"p. 156-157"},{"id":"d155-qroc-023","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":1,"question":"Dans le muguet, comment se comporte l'enduit blanchâtre de la face interne des joues lorsqu'on le racle ?","answer":"Il se détache facilement","accept":["se détache facilement","se détache","s'enlève facilement","s'enlève"],"keywords":["détach"],"explanation":"Le muguet est un érythème de la face interne des joues recouvert d'un enduit blanchâtre qui se détache facilement au raclage ; une dysphagie apparaît si l'extension gagne le pharynx.","src":"p. 157"},{"id":"d155-qroc-024","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":1,"question":"Quel est l'aspect classique des leucorrhées d'une vulvovaginite candidosique aiguë ?","answer":"Blanc jaunâtre, en « lait caillé »","accept":["lait caillé","blanc jaunâtre"],"keywords":["lait caillé"],"explanation":"La vulvovaginite aiguë associe érythème et œdème vulvovaginaux, enduit blanchâtre, leucorrhées souvent abondantes « lait caillé » et prurit souvent intense, avec extension fréquente aux plis inguinaux et interfessier.","src":"p. 158"},{"id":"d155-qroc-025","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["pièges"],"difficulty":2,"question":"Devant une balanite d'aspect douteux (le carcinome intra-épithélial fait partie des diagnostics différentiels), quel geste faut-il pratiquer au moindre doute ?","answer":"Une biopsie","accept":["biopsie","biopsie cutanée"],"keywords":["biopsie"],"explanation":"L'aspect de la balanite candidosique est peu spécifique (lésions érythémateuses, rarement pustuleuses, du gland, du sillon balano-préputial ou du prépuce) ; les diagnostics différentiels incluent la syphilis secondaire, l'herpès génital, le psoriasis et le carcinome in situ.","src":"p. 158"},{"id":"d155-qroc-026","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["diagnostic"],"difficulty":2,"question":"Quelle étiologie fongique est suggérée par un intertrigo des grands plis bilatéral et symétrique, à fond érythémateux et fissuré ?","answer":"Une candidose","accept":["candidose","candidosique","candida"],"keywords":["candid"],"explanation":"Les intertrigos candidosiques des grands plis sont bilatéraux et symétriques, à fond érythémateux fissuré recouvert d'un enduit crémeux ; l'intertrigo inguinal dermatophytique est classiquement unilatéral.","src":"p. 159"},{"id":"d155-qroc-027","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":1,"question":"Quels aspects peut prendre la bordure d'un intertrigo candidosique ?","answer":"Bordure pustuleuse ou collerette desquamative","accept":["pustuleuse ou collerette desquamative","pustules et collerette desquamative"],"keywords":["pustul","collerette"],"explanation":"L'intertrigo candidosique a un fond érythémateux recouvert d'un enduit crémeux malodorant, avec une fissure fréquente du fond du pli et une bordure pustuleuse ou en collerette desquamative ; l'évolution est chronique et souvent récidivante.","src":"p. 159"},{"id":"d155-qroc-028","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":1,"question":"Par quelle lésion débute habituellement une onychomycose candidosique ?","answer":"Un péri-onyxis (paronychie)","accept":["péri-onyxis","périonyxis","paronychie"],"keywords":["peri"],"explanation":"Le péri-onyxis (tuméfaction douloureuse du repli sus-unguéal, pus possible à la pression) précède l'envahissement de la tablette (onyxis), de teinte marron verdâtre ; l'évolution est chronique, par poussées.","src":"p. 161"},{"id":"d155-qroc-029","type":"QROC","rank":"A","objective":"d155-obj-03","tags":["prévention"],"difficulty":1,"question":"Devant une candidose récidivante, que faut-il rechercher en plus d'instituer un traitement antifongique ?","answer":"Des facteurs favorisants","accept":["facteurs favorisants","facteur favorisant","terrain favorisant"],"keywords":["favoris"],"explanation":"La prophylaxie et le traitement des candidoses ne se réduisent pas à l'antifongique local ou général : on recherche et on corrige les facteurs favorisants (macération, diabète, antibiotiques, immunodépression...), surtout dans les formes récidivantes.","src":"p. 166"},{"id":"d155-qroc-030","type":"QROC","rank":"B","objective":"d155-obj-06","tags":["traitement"],"difficulty":1,"question":"Quelle famille d'antifongiques locaux est utilisée en première intention dans les candidoses ?","answer":"Les imidazolés","accept":["imidazolés","imidazole","topiques imidazolés","dérivés imidazolés"],"keywords":["imidazol"],"explanation":"Les imidazolés topiques sont de première intention (1 à 2 applications par jour pendant 2 à 4 semaines) ; la forme galénique s'adapte à la localisation, sans poudre dans les plis car elle est irritante.","src":"p. 163-164"},{"id":"d155-qroc-031","type":"QROC","rank":"B","objective":"d155-obj-06","tags":["traitement","grossesse"],"difficulty":1,"question":"Chez quelle patiente aucun antifongique par voie orale n'est-il autorisé ?","answer":"La femme enceinte","accept":["femme enceinte","enceinte","grossesse"],"keywords":["enceinte"],"explanation":"Aucun antifongique per os n'est autorisé chez la femme enceinte, que ce soit pour une candidose ou pour une dermatophytose.","src":"p. 164, 174"},{"id":"d155-qroc-032","type":"QROC","rank":"A","objective":"d155-obj-01","tags":["définition"],"difficulty":1,"question":"Quels sont les trois genres de dermatophytes ?","answer":"Epidermophyton, Microsporum, Trichophyton","accept":[],"keywords":["epidermophyton","microsporum","trichophyton"],"explanation":"Les dermatophytes sont des champignons filamenteux des genres Epidermophyton, Microsporum et Trichophyton ; ils sont toujours pathogènes et ont une affinité pour la kératine.","src":"p. 166"},{"id":"d155-qroc-033","type":"QROC","rank":"A","objective":"d155-obj-03","tags":["étiologie"],"difficulty":1,"question":"Selon l'origine de la contamination (homme, animal, sol), comment nomme-t-on les trois catégories de dermatophytes ?","answer":"Anthropophiles, zoophiles, géophiles","accept":[],"keywords":["anthropophil","zoophil","géophil"],"explanation":"Anthropophiles : contamination interhumaine, souvent indirecte (sols, peignes, vêtements). Zoophiles : animaux d'élevage ou de compagnie (Microsporum canis, T. mentagrophytes). Géophiles : sol (M. gypseum).","src":"p. 167"},{"id":"d155-qroc-034","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["étiologie"],"difficulty":1,"question":"Quel dermatophyte est responsable de 70 à 80 % des dermatophytoses des plis ?","answer":"Trichophyton rubrum","accept":["T. rubrum","rubrum"],"keywords":["rubrum"],"explanation":"T. rubrum (70-80 %), T. interdigitale (15-20 %) et Epidermophyton floccosum (5 %) sont les trois dermatophytes à transmission interhumaine responsables des atteintes des plis.","src":"p. 167"},{"id":"d155-qroc-035","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":1,"question":"Quels espaces interorteils sont préférentiellement touchés par l'intertrigo dermatophytique ?","answer":"Les 3e et 4e espaces","accept":["3e et 4e espaces","3e et 4e","troisième et quatrième espaces","3 et 4"],"keywords":["3","4"],"explanation":"L'intertrigo interorteils touche surtout l'adulte et l'adolescent : desquamation sèche ou suintante, fissure, prurit variable. La candidose est rare aux pieds et siège le plus souvent au 1er espace.","src":"p. 167"},{"id":"d155-qroc-036","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["complications"],"difficulty":1,"question":"Quelle infection bactérienne de la jambe a fréquemment pour porte d'entrée un intertrigo interorteils ?","answer":"L'érysipèle","accept":["érysipèle de jambe","érysipèle"],"keywords":["érysipèle"],"explanation":"L'intertrigo interorteils est une porte d'entrée très fréquente de l'érysipèle de jambe ; il peut aussi s'étendre à l'ensemble du pied (tinea pedis).","src":"p. 167"},{"id":"d155-qroc-037","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["diagnostic"],"difficulty":2,"question":"Quelle est la latéralité classique d'un intertrigo inguinal d'origine dermatophytique ?","answer":"Unilatérale","accept":["unilatéral","unilatérale","atteinte unilatérale"],"keywords":["unilat"],"explanation":"L'atteinte des plis inguinaux est classiquement unilatérale, avec bordure active et guérison centrale ; le fond du pli n'est ni érythémateux ni fissuré. Une atteinte bilatérale et symétrique est plutôt candidosique.","src":"p. 168"},{"id":"d155-qroc-038","type":"QROC","rank":"A","objective":"d155-obj-04","tags":["clinique"],"difficulty":1,"question":"Quelle évolution caractérise les lésions de dermatophytose à bordure active ?","answer":"Évolution centrifuge avec guérison centrale","accept":["extension centrifuge","centrifuge","guérison centrale"],"keywords":["centrifuge","central"],"explanation":"Les lésions sont arrondies ou polycycliques, avec une bordure érythémateuse vésiculeuse et/ou squameuse très évocatrice, d'évolution centrifuge avec guérison centrale ; le prurit est parfois intense.","src":"p. 169, 176"},{"id":"d155-qroc-039","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":2,"question":"Comment nomme-t-on le tableau associant une kératodermie palmaire unilatérale et une kératodermie plantaire bilatérale au cours d'une dermatophytose ?","answer":"« One hand, two feet »","accept":["one hand two feet","one hand-two feet","two feet one hand","une main deux pieds","deux pieds une main"],"keywords":["hand"],"explanation":"La kératodermie est blanchâtre et farineuse, avec renforcement des plis palmo-plantaires, parfois associée à une atteinte unguéale ; le caractère unilatéral de l'atteinte palmaire est évocateur du diagnostic.","src":"p. 170, 176"},{"id":"d155-qroc-040","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on la teigne suppurée, très inflammatoire, due à un dermatophyte d'origine animale ou tellurique ?","answer":"Le kérion","accept":["kérion","kerion"],"keywords":["kérion"],"explanation":"Le kérion associe des lésions plurinodulaires croûteuses, très inflammatoires et douloureuses, avec de nombreux orifices pseudo-fistuleux laissant sourdre du pus sans véritable collection abcédée ; adénopathies et fièvre sont possibles.","src":"p. 171"},{"id":"d155-qroc-041","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["diagnostic"],"difficulty":2,"question":"Devant un cuir chevelu squameux, croûteux ou pustuleux avec alopécie, quel diagnostic faut-il évoquer ?","answer":"Une teigne","accept":["teigne","teigne du cuir chevelu"],"keywords":["teigne"],"explanation":"Tout état squameux, croûteux, pustuleux et alopécique du cuir chevelu doit faire évoquer une teigne ; l'examen mycologique est indispensable dans les atteintes phanériennes (cuir chevelu, ongles).","src":"p. 176"},{"id":"d155-qroc-042","type":"QROC","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":2,"question":"Dans l'onychomycose dermatophytique des orteils, quelle est la succession des lésions à partir de la partie distale ou latérale de la tablette ?","answer":"Leuconychie, hyperkératose sous-unguéale, onycholyse","accept":["leuconychie puis hyperkératose sous-unguéale puis onycholyse"],"keywords":["leuconychie","hyperkérat","onycholyse"],"explanation":"L'onyxis dermatophytique des orteils (T. rubrum dans 80 % des cas, T. interdigitale dans 20 %) est presque toujours associé à une atteinte interdigitale ou plantaire ; il débute par la partie distale et/ou latérale de la tablette.","src":"p. 173"},{"id":"d155-qroc-043","type":"QROC","rank":"B","objective":"d155-obj-05","tags":["paraclinique","pièges"],"difficulty":2,"question":"Pour quelle localisation l'examen mycologique n'est-il pas indispensable avant le traitement d'une dermatophytose ?","answer":"L'intertrigo interorteils","accept":["intertrigo interorteils","intertrigo des orteils","espaces interorteils","interorteils"],"keywords":["orteil"],"explanation":"L'examen mycologique est indispensable avant tout antifongique, local ou systémique (si besoin après une fenêtre thérapeutique d'au moins 2 semaines), sauf pour les intertrigos interorteils.","src":"p. 173"},{"id":"d155-qroc-044","type":"QROC","rank":"B","objective":"d155-obj-06","tags":["traitement"],"difficulty":2,"question":"Dans le traitement d'une teigne, quelle association est impérative ?","answer":"Traitement local + traitement systémique","accept":["local et systémique","local et général","traitement local et général"],"keywords":["local","systémique"],"explanation":"La teigne se traite 4 à 6 semaines, jusqu'à guérison clinique et mycologique, en associant impérativement traitement local et systémique ; on examine la famille et les sujets contacts si l'agent est anthropophile et on fait traiter l'animal s'il est zoophile.","src":"p. 175-176"},{"id":"d155-qroc-045","type":"QROC","rank":"B","objective":"d155-obj-06","tags":["traitement","pédiatrie"],"difficulty":2,"question":"Chez un enfant de plus de 10 kg ayant une teigne microsporique, quel antifongique oral prescrire et pendant combien de temps ?","answer":"Itraconazole pendant 6 semaines","accept":["itraconazole 6 semaines"],"keywords":["itraconazole","6"],"explanation":"Au-dessus de 10 kg : itraconazole 6 semaines pour une teigne microsporique, terbinafine 4 semaines pour une teigne trichophytique ou en traitement probabiliste. En dessous de 10 kg, la prise en charge est hospitalière.","src":"p. 176"},{"id":"d155-qru-101","type":"QRU","rank":"A","objective":"d155-obj-17","tags":["étiologie"],"difficulty":1,"stem":"Chez l'adulte, l'impétigo est rarement primitif. Quelle situation correspond à une impétiginisation ?","options":[{"t":"Surinfection bactérienne d'un eczéma","ok":true,"why":"L'impétiginisation est la complication infectieuse d'une dermatose sous-jacente (eczéma, varicelle) ou de lésions de grattage (gale, pédiculose)."},{"t":"Infection profonde et nécrosante d'un follicule pilo-sébacé","ok":false,"why":"C'est la définition du furoncle, pas celle d'une impétiginisation."},{"t":"Infection du repli unguéal par Staphylococcus aureus","ok":false,"why":"C'est un panaris."},{"t":"Collection de pus fluctuante des parties molles","ok":false,"why":"C'est un abcès."},{"t":"Ulcération creusant le derme chez un sujet en situation de précarité","ok":false,"why":"C'est l'ecthyma (impétigo creusant), pas une impétiginisation."}],"explanation":"L'impétiginisation est la surinfection bactérienne d'une dermatose préexistante (eczéma, varicelle) ou de lésions de grattage (gale, pédiculose) ; c'est la forme d'impétigo la plus fréquente chez l'adulte.","src":"p. 148"},{"id":"d155-qru-102","type":"QRU","rank":"A","objective":"d155-obj-21","tags":["diagnostic","urgence"],"difficulty":2,"stem":"Parmi ces tableaux d'impétigo, lequel est une forme grave justifiant un prélèvement bactériologique ?","options":[{"t":"Une lésion croûteuse unique de la joue chez un enfant de 4 ans","ok":false,"why":"Impétigo localisé : pas de prélèvement bactériologique."},{"t":"Trois lésions croûteuses péribuccales sur moins de 2 % de la surface cutanée","ok":false,"why":"Forme peu étendue (moins de 2 % de la surface, 6 lésions ou moins) : pas de prélèvement."},{"t":"Huit lésions croûteuses disséminées sur le tronc et les membres","ok":true,"why":"Plus de 6 lésions : critère de gravité, qui justifie un prélèvement bactériologique."},{"t":"Un impétigo apyrétique avec une adénopathie satellite","ok":false,"why":"L'absence de fièvre et une adénopathie satellite sont habituelles et ne définissent pas une forme grave."},{"t":"Un impétigo bulleux limité au pourtour de la bouche","ok":false,"why":"Une forme localisée n'est pas grave, même si elle est bulleuse."}],"explanation":"Les formes graves d'impétigo sont l'ecthyma, l'atteinte de plus de 2 % de la surface cutanée, la présence de plus de 6 lésions et l'extension rapide des lésions.","src":"p. 147, 149"},{"id":"d155-qru-103","type":"QRU","rank":"A","objective":"d155-obj-15","tags":["urgence","diagnostic"],"difficulty":2,"stem":"Une femme de 24 ans a manipulé un furoncle de l'aile du nez. Vingt-quatre heures plus tard apparaissent une fièvre, un œdème du visage et un cordon veineux induré palpable. Quel diagnostic évoquer en urgence ?","options":[{"t":"Impétigo péribuccal surinfecté","ok":false,"why":"L'impétigo associe croûtes mélicériques et absence de fièvre, sans œdème fébrile du visage."},{"t":"Staphylococcie maligne de la face","ok":true,"why":"Fièvre, œdème du visage et cordon veineux induré après manipulation d'un furoncle de la zone dangereuse du visage : c'est une urgence (thrombophlébite superficielle septique)."},{"t":"Folliculite de la barbe (sycosis)","ok":false,"why":"Le sycosis est une folliculite de la barbe, favorisée par le rasage."},{"t":"Abcès des parties molles du visage","ok":false,"why":"L'abcès est une collection de pus fluctuante, qui n'explique pas le cordon veineux ni l'œdème fébrile du visage."},{"t":"Panaris du repli unguéal","ok":false,"why":"Le panaris est une infection du repli unguéal, sans rapport avec ce tableau."}],"explanation":"La staphylococcie maligne de la face est une urgence : elle complique la manipulation intempestive d'un furoncle de la zone délimitée par le canthus interne, la commissure labiale et l'aile du nez.","src":"p. 151"},{"id":"d155-qru-104","type":"QRU","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":1,"stem":"Quelle forme de candidose buccale correspond à un intertrigo de la commissure labiale, avec un fond de pli érythémateux et fissuraire ?","options":[{"t":"Perlèche","ok":true,"why":"La perlèche est l'intertrigo de la commissure labiale, uni- ou bilatéral, pouvant gagner la peau adjacente et la lèvre."},{"t":"Glossite","ok":false,"why":"La glossite est une langue rouge et dépapillée."},{"t":"Stomatite","ok":false,"why":"La stomatite est une inflammation de la muqueuse buccale (sécheresse, sensation cuisante, muqueuse rouge et vernissée)."},{"t":"Muguet","ok":false,"why":"Le muguet est un enduit blanchâtre de la face interne des joues, qui se détache au raclage."},{"t":"Candidose œsophagienne","ok":false,"why":"Elle provient le plus souvent de l'extension d'une candidose buccale chez un patient immunodéprimé."}],"explanation":"Les quatre formes de candidose buccale sont la perlèche (commissure labiale), la glossite (langue rouge dépapillée), la stomatite et le muguet.","src":"p. 156-157"},{"id":"d155-qru-105","type":"QRU","rank":"A","objective":"d155-obj-01","tags":["définition"],"difficulty":1,"stem":"Laquelle de ces affirmations concernant les dermatophytes est exacte ?","options":[{"t":"Ils sont toujours pathogènes et respectent les muqueuses","ok":true,"why":"Les dermatophytes ne sont jamais saprophytes et ne touchent jamais les muqueuses."},{"t":"Ils sont des saprophytes habituels de la peau saine","ok":false,"why":"Ils ne sont saprophytes ni de la peau, ni des muqueuses, ni des phanères."},{"t":"Ils atteignent surtout les muqueuses digestive et génitale","ok":false,"why":"Ce sont les candidoses qui touchent davantage les muqueuses ; les dermatophytes les respectent."},{"t":"Ce sont des levures du genre Candida","ok":false,"why":"Les dermatophytes sont des champignons filamenteux (Epidermophyton, Microsporum, Trichophyton)."},{"t":"Ils ont une affinité pour les graisses cutanées","ok":false,"why":"Ils ont une affinité pour la kératine (couche cornée, poils, cheveux, ongles)."}],"explanation":"Les dermatophytes sont des champignons filamenteux kératinophiles, toujours pathogènes, qui respectent toujours les muqueuses.","src":"p. 166"},{"id":"d155-qru-106","type":"QRU","rank":"A","objective":"d155-obj-02","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un adulte présente un placard inguinal unilatéral, prurigineux, à bordure érythémato-squameuse vésiculeuse, d'évolution centrifuge avec guérison centrale. Quel est le diagnostic le plus probable ?","options":[{"t":"Intertrigo candidosique des grands plis","ok":false,"why":"Il est bilatéral et symétrique, avec un fond de pli érythémateux fissuré et une bordure pustuleuse ou en collerette."},{"t":"Intertrigo dermatophytique inguinal","ok":true,"why":"Placard unilatéral à bordure active et guérison centrale, résultant le plus souvent d'une auto-inoculation à partir d'une mycose des pieds."},{"t":"Psoriasis inversé des plis inguinaux","ok":false,"why":"C'est un intertrigo vernissé et bien limité, sans bordure active ni aspect en collerette."},{"t":"Érythrasma inguinal à corynébactéries","ok":false,"why":"L'érythrasma est brun chamoisé, de teinte homogène et asymptomatique."},{"t":"Dermatite de contact par irritation","ok":false,"why":"Elle n'explique pas la bordure active vésiculeuse d'évolution centrifuge avec guérison centrale."}],"explanation":"L'intertrigo dermatophytique inguinal est classiquement unilatéral, avec une bordure active et une guérison centrale, et le fond du pli n'est ni érythémateux ni fissuré.","src":"p. 168-169"},{"id":"d155-qru-107","type":"QRU","rank":"A","objective":"d155-obj-02","tags":["clinique"],"difficulty":2,"stem":"Quel tableau correspond à un kérion ?","options":[{"t":"Plaque alopécique unique, grande, squameuse, avec cheveux cassés courts","ok":false,"why":"C'est une teigne tondante microsporique."},{"t":"Multiples petites plaques alopéciques squameuses engluant des cheveux cassés","ok":false,"why":"C'est une teigne tondante trichophytique."},{"t":"Nodules très inflammatoires avec orifices pseudo-fistuleux purulents","ok":true,"why":"Le kérion est une teigne suppurée, croûteuse, douloureuse, avec écoulement purulent et sanglant sans réelle collection abcédée."},{"t":"Cuir chevelu squameux, non alopéciant, évoquant un psoriasis","ok":false,"why":"Le psoriasis et la dermatite séborrhéique du cuir chevelu ne sont pas alopéciants."},{"t":"Plaque alopécique sans aucune squame, ni inflammation","ok":false,"why":"C'est une pelade : il n'y a pas de squame."}],"explanation":"Le kérion est une teigne suppurée très inflammatoire, due à un dermatophyte d'origine animale ou tellurique ; il est parfois secondaire à l'application d'une corticothérapie locale.","src":"p. 171, 173"},{"id":"d155-qru-108","type":"QRU","rank":"B","objective":"d155-obj-06","tags":["traitement","pédiatrie"],"difficulty":2,"stem":"Un enfant de 6 ans (15 kg) a une teigne microsporique documentée. Quel traitement antifongique oral est indiqué ?","options":[{"t":"Terbinafine pendant 4 semaines","ok":false,"why":"Ce schéma correspond à une teigne trichophytique ou à un traitement probabiliste."},{"t":"Terbinafine pendant 6 semaines","ok":false,"why":"La terbinafine se donne 4 semaines, et pas pour la teigne microsporique."},{"t":"Itraconazole pendant 6 semaines","ok":true,"why":"Chez l'enfant de plus de 10 kg, la teigne microsporique relève de l'itraconazole pendant 6 semaines, associé au traitement local."},{"t":"Itraconazole pendant 4 semaines","ok":false,"why":"La durée est de 6 semaines pour la teigne microsporique."},{"t":"Un antifongique local seul pendant 6 semaines","ok":false,"why":"L'association d'un traitement local et d'un traitement systémique est impérative dans la teigne."}],"explanation":"Teigne chez l'enfant de plus de 10 kg : itraconazole 6 semaines si teigne microsporique ; terbinafine 4 semaines si teigne trichophytique ou en traitement probabiliste ; traitement local associé.","src":"p. 175-176"},{"id":"d155-qcm-101","type":"QRM","rank":"A","objective":"d155-obj-18","tags":["clinique","pédiatrie"],"difficulty":1,"stem":"Un garçon de 5 ans présente depuis 3 jours des vésicules puis des croûtes jaunâtres autour de la bouche, sans fièvre, avec un état général conservé. Parmi les propositions suivantes, lesquelles sont exactes ?","options":[{"t":"Le germe le plus souvent en cause en France est Staphylococcus aureus","ok":true,"why":"S. aureus est en cause dans environ 90 % des impétigos en France."},{"t":"L'affection est très contagieuse (auto-inoculation, petites épidémies familiales ou de collectivité)","ok":true,"why":"La contagiosité est importante, d'où les épidémies familiales ou en collectivité."},{"t":"Le diagnostic est clinique : aucun prélèvement bactériologique n'est nécessaire dans cette forme localisée","ok":true,"why":"Impétigo localisé ou peu étendu : pas de prélèvement bactériologique."},{"t":"Une fièvre élevée avec altération de l'état général est habituelle dans ce tableau","ok":false,"why":"L'état général est conservé, sans fièvre ; une adénopathie satellite est possible."},{"t":"Streptococcus pyogenes est le seul germe en cause en France","ok":false,"why":"S. pyogenes domine surtout dans les pays émergents ; les deux germes peuvent aussi s'associer."}],"explanation":"L'impétigo est une infection contagieuse de l'épiderme, à S. aureus dans environ 90 % des cas en France ; le diagnostic est clinique et un impétigo localisé ne se prélève pas.","src":"p. 147"},{"id":"d155-qcm-102","type":"QRM","rank":"B","objective":"d155-obj-20","tags":["traitement","pédiatrie"],"difficulty":2,"stem":"Un enfant a un impétigo localisé et peu étendu. Quelles propositions de prise en charge sont exactes ?","options":[{"t":"Soins de toilette quotidiens à l'eau et au savon, avec rinçage soigneux","ok":true,"why":"Ces soins de toilette font partie de la prise en charge de tout impétigo."},{"t":"Mupirocine locale 2 à 3 fois par jour pendant 5 jours","ok":true,"why":"C'est l'antibiothérapie locale de l'impétigo localisé ou peu étendu."},{"t":"Éviction de la collectivité pendant 3 jours après le début du traitement si les lésions ne sont pas couvrables","ok":true,"why":"Si les lésions ne peuvent pas être couvertes par un pansement, l'éviction dure 3 jours après le début du traitement."},{"t":"Application d'un antiseptique local après la toilette, pour limiter la surinfection","ok":false,"why":"Il ne faut pas appliquer d'antiseptiques locaux."},{"t":"Antibiothérapie orale de 7 jours d'emblée, sans attendre un prélèvement","ok":false,"why":"L'antibiothérapie orale de 7 jours est réservée aux formes graves d'impétigo."}],"explanation":"L'impétigo localisé ou peu étendu relève de soins de toilette, sans antiseptique, et de la mupirocine locale pendant 5 jours ; l'antibiothérapie orale est réservée aux formes graves.","src":"p. 149"},{"id":"d155-qcm-103","type":"QRM","rank":"B","objective":"d155-obj-20","tags":["traitement"],"difficulty":3,"stem":"Un adulte a un impétigo avec plus de 6 lésions et une extension rapide. Quelles propositions thérapeutiques sont exactes ?","options":[{"t":"Antibiothérapie orale de 7 jours, sans attendre le résultat du prélèvement bactériologique","ok":true,"why":"Dans les formes graves, l'antibiothérapie orale de 7 jours est débutée sans attendre les résultats."},{"t":"Pristinamycine ou céfalexine","ok":true,"why":"Ce sont les antibiotiques cités chez l'adulte."},{"t":"Mupirocine locale associée au traitement oral","ok":false,"why":"Il n'y a pas d'antibiothérapie locale dans les formes graves."},{"t":"Amoxicilline-acide clavulanique ou céfadroxil, qui sont les options de l'adulte","ok":false,"why":"Ce sont les options de l'enfant ; chez l'adulte on utilise la pristinamycine ou la céfalexine."},{"t":"Il faut d'emblée choisir un antibiotique actif sur le SARM","ok":false,"why":"Il n'est pas nécessaire de prendre en compte le SARM dans le traitement probabiliste de première intention."}],"explanation":"Forme grave d'impétigo : antibiothérapie orale de 7 jours (adulte : pristinamycine ou céfalexine ; enfant : amoxicilline-acide clavulanique ou céfadroxil, josamycine si allergie aux pénicillines), sans antibiothérapie locale.","src":"p. 149"},{"id":"d155-qcm-104","type":"QRM","rank":"A","objective":"d155-obj-12","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Un homme de 35 ans consulte pour un nodule très inflammatoire et douloureux de la nuque, qui évolue depuis 6 jours vers une nécrose centrale avec élimination d'un bourbillon. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'un furoncle","ok":true,"why":"Lésion papulo-nodulaire très inflammatoire évoluant en 5 à 10 jours vers la nécrose folliculaire avec bourbillon."},{"t":"Le germe le plus souvent en cause est Staphylococcus aureus","ok":true,"why":"Le furoncle est dû à S. aureus."},{"t":"Un prélèvement bactériologique du pus est systématique, même pour un furoncle isolé","ok":false,"why":"Pour un furoncle isolé, il n'y a pas de prélèvement bactériologique ; il est réservé aux furoncles compliqués."},{"t":"Il s'agit d'une folliculite superficielle de l'ostium folliculaire","ok":false,"why":"La folliculite superficielle est une pustule centrée par un poil ; le furoncle est profond et nécrosant."},{"t":"Le bourbillon correspond au pus collecté sous la peau","ok":false,"why":"Le bourbillon est le follicule pileux nécrosé qui s'élimine."}],"explanation":"Le furoncle est une infection profonde et nécrosante du follicule pilo-sébacé due à S. aureus ; il évolue vers la nécrose et l'élimination d'un bourbillon, sans prélèvement s'il est isolé.","src":"p. 150"},{"id":"d155-qcm-105","type":"QRM","rank":"A","objective":"d155-obj-23","tags":["clinique"],"difficulty":1,"stem":"À propos des signes cliniques d'une folliculite superficielle, quelles propositions sont exactes ?","options":[{"t":"La lésion élémentaire est une pustule centrée par un poil, avec un érythème périfolliculaire","ok":true,"why":"C'est la lésion élémentaire de la folliculite superficielle."},{"t":"Les lésions, en nombre variable, siègent sur les régions pileuses (cuisses, périnée, bras, thorax, dos)","ok":true,"why":"Elles touchent les zones où il y a des poils."},{"t":"La folliculite d'un cil s'appelle un orgelet","ok":true,"why":"L'orgelet est la folliculite d'un cil."},{"t":"La folliculite de la barbe s'appelle un sycosis ; le rasage favorise son extension et sa chronicité","ok":true,"why":"Le rasage favorise l'extension et la chronicité du sycosis."},{"t":"Les lésions sont profondes et nécrosantes, avec élimination d'un bourbillon, et atteignent le derme","ok":false,"why":"C'est la description du furoncle ; la folliculite superficielle est une pustule centrée par un poil."}],"explanation":"La folliculite superficielle est une pustule centrée par un poil, avec érythème périfolliculaire, sur les régions pileuses ; l'orgelet (cil) et le sycosis (barbe) en sont deux formes.","src":"p. 150"},{"id":"d155-qcm-106","type":"QRM","rank":"A","objective":"d155-obj-15","tags":["urgence","complications"],"difficulty":2,"stem":"À propos de la staphylococcie maligne de la face, quelles propositions sont exactes ?","options":[{"t":"Elle complique la manipulation d'un furoncle de la zone canthus interne - commissure labiale - aile du nez","ok":true,"why":"C'est la zone dangereuse du visage : la manipulation intempestive du furoncle est en cause."},{"t":"Elle associe fièvre, altération de l'état général et œdème du visage, avec parfois un cordon veineux induré","ok":true,"why":"Tableau clinique caractéristique de cette urgence."},{"t":"Son mécanisme est une thrombophlébite superficielle septique, source d'un cordon veineux induré","ok":true,"why":"Le cordon veineux palpable correspond à la thrombophlébite superficielle septique."},{"t":"C'est une complication fréquente des furoncles du visage, de pronostic le plus souvent bénin","ok":false,"why":"Elle est exceptionnelle et grave : c'est une urgence, avec un risque vital."},{"t":"Son mécanisme est une thrombophlébite veineuse profonde aseptique, sans risque pour le sinus caverneux","ok":false,"why":"Le mécanisme est une thrombophlébite superficielle septique ; la complication majeure est la thrombophlébite du sinus caverneux, qui engage le pronostic vital."}],"explanation":"Complication exceptionnelle mais grave du furoncle de la face manipulé : thrombophlébite superficielle septique pouvant se compliquer d'une thrombophlébite du sinus caverneux, qui engage le pronostic vital.","src":"p. 151-152"},{"id":"d155-qcm-107","type":"QRM","rank":"B","objective":"d155-obj-09","tags":["traitement","diagnostic"],"difficulty":2,"stem":"Un homme de 30 ans a un nodule érythémateux très douloureux de la cuisse, devenu fluctuant en quelques jours, sans fièvre. Quelles propositions sont exactes ?","options":[{"t":"C'est une collection de pus, dont le traitement comporte une incision et un drainage","ok":true,"why":"Le traitement de l'abcès est médical et chirurgical : incision et drainage."},{"t":"Un prélèvement bactériologique est systématique (identification, toxines, antibiogramme)","ok":true,"why":"Le prélèvement est systématique dans l'abcès."},{"t":"Une antibiothérapie orale de 5 jours peut être associée (clindamycine, pristinamycine, oxacilline...)","ok":true,"why":"Elle complète l'incision-drainage."},{"t":"Une fièvre élevée avec altération de l'état général est constamment présente","ok":false,"why":"La fièvre est souvent absente et l'état général conservé."},{"t":"L'antibiothérapie orale seule suffit, sans incision ni drainage de la collection","ok":false,"why":"Le traitement est médical et chirurgical : incision et drainage."}],"explanation":"L'abcès est une collection de pus : incision et drainage, prélèvement bactériologique systématique et antibiothérapie orale de 5 jours.","src":"p. 153"},{"id":"d155-qcm-108","type":"QRM","rank":"B","objective":"d155-obj-16","tags":["étiologie","traitement"],"difficulty":2,"stem":"Un patient présente depuis plusieurs mois des furoncles à répétition. Quelles propositions sont exactes ?","options":[{"t":"On parle de furonculose","ok":true,"why":"La furonculose est la répétition de furoncles pendant plusieurs mois, voire des années."},{"t":"On recherche un portage de staphylocoques (nez, gorge, anus, périnée) par des prélèvements","ok":true,"why":"Ces gîtes bactériens sont à dépister par des prélèvements."},{"t":"Après la guérison d'une poussée, on décolonise les gîtes bactériens du patient et de son entourage","ok":true,"why":"La décolonisation concerne aussi les personnes vivant sous le même toit et les contacts proches."},{"t":"La décolonisation ne concerne que le patient, jamais son entourage","ok":false,"why":"Elle concerne le patient et son entourage."},{"t":"Un diabète est retrouvé dans tous les cas de furonculose et en est la cause unique","ok":false,"why":"Le rôle de facteurs favorisants comme le diabète ou l'immunodépression est seulement discuté."}],"explanation":"Furonculose : recherche d'un portage staphylococcique et, après la poussée, décolonisation du patient et de son entourage (mupirocine nasale, chlorhexidine moussante, hygiène).","src":"p. 151-152"},{"id":"d155-qcm-109","type":"QRM","rank":"A","objective":"d155-obj-03","tags":["physiopathologie"],"difficulty":3,"stem":"Parmi les propositions suivantes concernant Candida albicans, laquelle (lesquelles) est (sont) exacte(s) ?","options":[{"t":"Il est un saprophyte habituel de la peau saine","ok":false,"why":"Il n'est jamais présent sur la peau saine."},{"t":"Il n'est jamais présent sur la peau saine","ok":true,"why":"C'est un endosaprophyte des muqueuses digestive et génitale, pas de la peau."},{"t":"La contamination se fait principalement par voie exogène","ok":false,"why":"La voie endogène est la principale, à partir du réservoir digestif ou génital."},{"t":"Il est pathogène uniquement chez le sujet immunodéprimé","ok":false,"why":"Il devient pathogène sous l'influence de facteurs locaux ou généraux : macération, antibiotiques, diabète, grossesse..."},{"t":"Il fait partie des dermatophytes","ok":false,"why":"C'est une levure du genre Candida, pas un champignon filamenteux dermatophyte."}],"explanation":"C. albicans est un endosaprophyte des muqueuses digestive et génitale, pathogène d'opportunité, jamais présent sur la peau saine ; l'infection est principalement endogène.","src":"p. 155"},{"id":"d155-qcm-110","type":"QRM","rank":"A","objective":"d155-obj-04","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Une femme de 78 ans, porteuse d'une prothèse dentaire, se plaint d'une sécheresse buccale et d'une sensation de brûlure. Elle a une langue rouge et dépapillée et un érythème de la face interne des joues recouvert d'un enduit blanchâtre qui se détache au raclage. Quelles propositions sont exactes ?","options":[{"t":"Une candidose buccale est le diagnostic le plus probable","ok":true,"why":"Langue rouge dépapillée (glossite) et enduit blanchâtre se détachant au raclage (muguet) évoquent une candidose buccale."},{"t":"La langue rouge dépapillée correspond à une glossite et l'enduit blanchâtre à un muguet","ok":true,"why":"Ce sont deux des quatre formes de candidose buccale."},{"t":"La prothèse dentaire est un facteur favorisant par irritation locale","ok":true,"why":"L'âge et la prothèse dentaire (irritation locale) favorisent la candidose buccale."},{"t":"Un prélèvement mycologique est obligatoire avant tout traitement, même dans ce tableau typique","ok":false,"why":"Il n'est pas toujours pratiqué en routine si la présentation clinique est évidente ou si un traitement d'épreuve local est efficace."},{"t":"Un enduit adhérent, impossible à détacher, est typique du muguet","ok":false,"why":"Dans le muguet, l'enduit blanchâtre se détache facilement au raclage."}],"explanation":"Le muguet (enduit blanchâtre se détachant au raclage) et la glossite (langue rouge dépapillée) sont des formes de candidose buccale ; la clinique suffit souvent.","src":"p. 156-157, 162"},{"id":"d155-qcm-111","type":"QRM","rank":"A","objective":"d155-obj-02","tags":["clinique","grossesse"],"difficulty":2,"stem":"Une femme de 27 ans, enceinte, consulte pour un prurit vulvaire intense avec des leucorrhées blanc jaunâtre abondantes. Quelles propositions sont exactes ?","options":[{"t":"Une vulvovaginite candidosique aiguë est probable","ok":true,"why":"Prurit souvent intense et leucorrhées blanc jaunâtre abondantes en contexte de grossesse."},{"t":"Les leucorrhées ont classiquement un aspect de « lait caillé »","ok":true,"why":"Aspect classique, avec stagnation dans les plis de la muqueuse vulvovaginale."},{"t":"Une extension aux plis inguinaux et au pli interfessier est possible","ok":true,"why":"Elle est fréquente dans la vulvovaginite aiguë."},{"t":"La grossesse rend ce diagnostic improbable, car elle protège des infections muqueuses","ok":false,"why":"La grossesse est un contexte favorisant : la vulvovaginite candidosique est fréquente chez la femme jeune et enceinte."},{"t":"Cette affection survient surtout chez la femme de plus de 50 ans, après la ménopause","ok":false,"why":"Elle touche les femmes jeunes et d'âge moyen et est rare après 50 ans."}],"explanation":"La vulvovaginite candidosique aiguë touche surtout la femme jeune ou enceinte : érythème, œdème, leucorrhées « lait caillé », prurit intense ± dyspareunie.","src":"p. 158"},{"id":"d155-qcm-112","type":"QRM","rank":"A","objective":"d155-obj-02","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Une patiente obèse et diabétique de 55 ans présente un intertrigo sous-mammaire bilatéral et symétrique : fond du pli érythémateux et fissuré, enduit blanchâtre, bordure en collerette avec pustules. Quelles propositions sont exactes ?","options":[{"t":"Une candidose est le diagnostic le plus probable","ok":true,"why":"Fond érythémateux fissuré, enduit, collerette avec pustules et atteinte bilatérale symétrique sont typiques."},{"t":"L'obésité et le diabète sont des facteurs favorisants","ok":true,"why":"Macération, obésité et diabète favorisent les intertrigos candidosiques."},{"t":"Le diagnostic est clinique ; la mycologie est réservée aux cas atypiques","ok":true,"why":"Le diagnostic de candidose est clinique, confirmé par l'examen mycologique dans les cas atypiques ou certaines topographies."},{"t":"Le caractère bilatéral et symétrique oriente plutôt vers une dermatophytose","ok":false,"why":"L'atteinte bilatérale et symétrique est en faveur d'une origine candidosique."},{"t":"On s'attend à un fond du pli ni érythémateux ni fissuré","ok":false,"why":"Ce caractère est celui de l'intertrigo dermatophytique ; dans la candidose, le fond du pli est érythémateux et fissuré."}],"explanation":"Intertrigo des grands plis bilatéral et symétrique, à fond érythémateux fissuré, enduit crémeux et collerette pustuleuse : candidose, favorisée par obésité, diabète et macération.","src":"p. 159, 166"},{"id":"d155-qcm-113","type":"QRM","rank":"B","objective":"d155-obj-05","tags":["paraclinique"],"difficulty":2,"stem":"À propos de l'examen mycologique dans les candidoses, quelles propositions sont exactes ?","options":[{"t":"Il est indiqué en cas d'atypie clinique ou de doute diagnostique, avant tout traitement","ok":true,"why":"Il faut prélever avant de traiter."},{"t":"Il est indiqué devant des lésions chroniques ou récidivantes, ou en cas de résistance à un traitement bien suivi","ok":true,"why":"Ce sont deux autres indications."},{"t":"Écouvillon pour une lésion cutanéo-muqueuse ; fragment de tablette découpé pour un ongle","ok":true,"why":"Telles sont les modalités de prélèvement."},{"t":"La culture sur milieu de Sabouraud demande 3 à 4 semaines pour obtenir l'espèce en cause","ok":false,"why":"Pour Candida, les colonies se développent en 48 heures ; le délai de 3 à 4 semaines concerne les dermatophytes."},{"t":"L'isolement de C. albicans sur un site muqueux prouve toujours une candidose, quel que soit le nombre de colonies","ok":false,"why":"Sur une muqueuse, C. albicans peut être saprophyte : l'interprétation tient compte du nombre de colonies et de la présence de filaments."}],"explanation":"Examen mycologique des candidoses : indiqué si atypie, lésions chroniques ou récidivantes, résistance au traitement ; écouvillon ou fragment d'ongle ; culture de Sabouraud en 48 heures.","src":"p. 162-163"},{"id":"d155-qcm-114","type":"QRM","rank":"B","objective":"d155-obj-06","tags":["traitement","grossesse"],"difficulty":2,"stem":"À propos du traitement des candidoses, quelles propositions sont exactes ?","options":[{"t":"On traite les facteurs favorisants et, simultanément, tous les foyers","ok":true,"why":"Ce sont deux principes de la prise en charge."},{"t":"Les topiques imidazolés sont utilisés en première intention","ok":true,"why":"Les imidazolés locaux sont de première intention."},{"t":"Aucun antifongique par voie orale n'est autorisé chez la femme enceinte","ok":true,"why":"Contre-indication de tout antifongique per os pendant la grossesse."},{"t":"Dans les plis, la forme poudre est à privilégier car elle assèche la lésion","ok":false,"why":"Il ne faut pas de poudre dans les plis : elle est irritante."},{"t":"Le fluconazole oral est le traitement de première intention de toute candidose cutanée localisée","ok":false,"why":"La voie orale est réservée aux candidoses oropharyngées et œsophagiennes de l'immunodéprimé ; les formes simples relèvent d'un traitement local."}],"explanation":"Candidoses : traiter les facteurs favorisants et tous les foyers, imidazolés locaux en première intention, pas de poudre dans les plis, aucun antifongique oral pendant la grossesse.","src":"p. 163-164"},{"id":"d155-qcm-115","type":"QRM","rank":"A","objective":"d155-obj-03","tags":["étiologie"],"difficulty":2,"stem":"À propos de la contamination par les dermatophytes, quelles propositions sont exactes ?","options":[{"t":"Les espèces anthropophiles (T. rubrum) se transmettent entre humains, souvent de façon indirecte","ok":true,"why":"Transmission interhumaine, directe ou surtout indirecte."},{"t":"Les espèces zoophiles (M. canis...) viennent des animaux et peuvent donner des lésions inflammatoires","ok":true,"why":"Non adaptés à l'homme, ils donnent des lésions inflammatoires."},{"t":"La macération (chaussures fermées, séchage insuffisant) favorise la contamination","ok":true,"why":"La macération est un facteur favorisant."},{"t":"Les espèces géophiles se transmettent exclusivement de personne à personne, par des squames","ok":false,"why":"Les espèces géophiles se transmettent par le sol, directement ou via un animal vecteur."},{"t":"En cas de teigne anthropophile, il n'existe aucun risque d'épidémie familiale ou en collectivité","ok":false,"why":"Il existe un risque d'épidémie en cas de teigne."}],"explanation":"Trois origines de contamination : homme (anthropophiles), animal (zoophiles) et sol (géophiles) ; la macération et l'altération de l'épiderme sont des facteurs favorisants.","src":"p. 166-167"},{"id":"d155-qcm-116","type":"QRM","rank":"A","objective":"d155-obj-02","tags":["clinique","complications"],"difficulty":2,"stem":"Un homme de 35 ans, sportif, a une desquamation avec fissure des 3e et 4e espaces interorteils, légèrement prurigineuse. Quelles propositions sont exactes ?","options":[{"t":"Une dermatophytose à Trichophyton rubrum est probable","ok":true,"why":"Dermatophytose des plis : T. rubrum est le plus fréquent, et la contamination est fréquente en milieu sportif."},{"t":"Cet intertrigo est une porte d'entrée fréquente de l'érysipèle de jambe","ok":true,"why":"Porte d'entrée très fréquente de l'érysipèle de jambe."},{"t":"L'infection peut s'étendre à l'ensemble du pied (tinea pedis)","ok":true,"why":"Extension locorégionale possible."},{"t":"La candidose est la cause la plus fréquente à ce niveau, avec un siège habituel aux 3e et 4e espaces","ok":false,"why":"La candidose est rare aux pieds et siège le plus souvent au 1er espace."},{"t":"Les muqueuses sont fréquemment atteintes, comme dans les candidoses","ok":false,"why":"Les dermatophytes respectent toujours les muqueuses."}],"explanation":"Intertrigo des 3e et 4e espaces : dermatophytose (T. rubrum), porte d'entrée de l'érysipèle de jambe, extension possible à tout le pied.","src":"p. 167"},{"id":"d155-qcm-117","type":"QRM","rank":"A","objective":"d155-obj-02","tags":["clinique","pédiatrie"],"difficulty":3,"stem":"Un enfant de 7 ans présente une plaque alopécique unique, arrondie et squameuse de 4 cm, sur laquelle les cheveux sont cassés à quelques millimètres de la peau. Quelles propositions sont exactes ?","options":[{"t":"Une teigne tondante microsporique est probable","ok":true,"why":"Plaque alopécique squameuse de grande taille, unique, cheveux cassés régulièrement à quelques millimètres."},{"t":"Les teignes touchent surtout l'enfant prépubertaire","ok":true,"why":"Moins fréquentes chez l'adolescent et rares chez l'adulte."},{"t":"Une transmission indirecte par bonnets ou matériel de coiffure est possible","ok":true,"why":"Elle peut provoquer de petites épidémies intrafamiliales."},{"t":"Il s'agit d'un kérion, teigne suppurée très inflammatoire","ok":false,"why":"Le kérion est une teigne suppurée plurinodulaire, très inflammatoire."},{"t":"La teigne est une maladie infectieuse à déclaration obligatoire","ok":false,"why":"La teigne n'est pas à déclaration obligatoire."}],"explanation":"Teigne microsporique : grande plaque alopécique squameuse unique chez l'enfant prépubertaire, cheveux cassés courts ; transmission possible par bonnets et matériel de coiffure.","src":"p. 171"},{"id":"d155-qcm-118","type":"QRM","rank":"B","objective":"d155-obj-05","tags":["paraclinique"],"difficulty":2,"stem":"À propos du diagnostic mycologique d'une dermatophytose, quelles propositions sont exactes ?","options":[{"t":"L'examen mycologique est indispensable avant le traitement, sauf pour les intertrigos interorteils","ok":true,"why":"Il précède tout antifongique, sauf dans l'intertrigo interorteils."},{"t":"Si un antifongique a déjà été appliqué, une fenêtre thérapeutique d'au moins 2 semaines peut être utile","ok":true,"why":"La fenêtre thérapeutique est d'au moins 2 semaines si besoin."},{"t":"On prélève des squames, des cheveux ou des fragments d'ongle, sans écouvillonnage","ok":true,"why":"Pas d'écouvillonnage : prélèvement de squames ou de phanères atteints."},{"t":"La culture sur milieu de Sabouraud donne le résultat en 48 heures","ok":false,"why":"La culture des dermatophytes est longue : 3 à 4 semaines."},{"t":"La biopsie cutanée est l'examen de référence pour confirmer le diagnostic","ok":false,"why":"Le diagnostic mycologique sur biopsie est fortuit, avec des filaments identifiés par la coloration PAS ; elle n'est pas l'examen de référence."}],"explanation":"Dermatophytose : mycologie avant tout traitement (sauf interorteils), squames ou phanères sans écouvillon, culture de 3 à 4 semaines ; la biopsie n'est pas l'examen de référence.","src":"p. 173-174"},{"id":"d155-qcm-119","type":"QRM","rank":"B","objective":"d155-obj-06","tags":["traitement","pédiatrie"],"difficulty":3,"stem":"À propos du traitement d'une teigne, quelles propositions sont exactes ?","options":[{"t":"Il associe impérativement un traitement local et un traitement systémique","ok":true,"why":"L'association est impérative."},{"t":"Il est poursuivi 4 à 6 semaines, jusqu'à guérison clinique et mycologique","ok":true,"why":"Durée de 4 à 6 semaines, jusqu'à guérison complète."},{"t":"Si l'agent est zoophile, l'animal doit être traité par un vétérinaire","ok":true,"why":"Il faut faire traiter l'animal."},{"t":"Un traitement local seul est suffisant chez l'enfant","ok":false,"why":"L'association local et systémique est impérative."},{"t":"Si l'agent est anthropophile, seul l'enfant atteint est examiné","ok":false,"why":"Il faut examiner toute la famille et les sujets contacts."}],"explanation":"Teigne : traitement local et systémique associés pendant 4 à 6 semaines, examen de la famille et des contacts si agent anthropophile, traitement de l'animal si agent zoophile.","src":"p. 175-176"},{"id":"d155-qcm-120","type":"QRM","rank":"A","objective":"d155-obj-02","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Aux doigts, quels éléments orientent vers une onychomycose dermatophytique plutôt que candidosique ?","options":[{"t":"Absence de péri-onyxis","ok":true,"why":"L'absence de péri-onyxis oriente vers un dermatophyte."},{"t":"Leuconychie blanc ivoire","ok":true,"why":"La leuconychie blanc ivoire est évocatrice d'un dermatophyte."},{"t":"Tuméfaction douloureuse du repli sus-unguéal avec pus à la pression","ok":false,"why":"C'est le péri-onyxis de la candidose unguéale."},{"t":"Teinte marron verdâtre de la tablette dans ses régions proximales et latérales","ok":false,"why":"C'est l'onyxis d'origine candidosique."},{"t":"Surinfection fréquente par le bacille pyocyanique","ok":false,"why":"Elle est fréquente dans l'onychomycose candidosique (teinte bleu-vert)."}],"explanation":"Aux doigts, l'onyxis dermatophytique est moins fréquent que l'onyxis candidosique : absence de péri-onyxis et leuconychie blanc ivoire en faveur d'un dermatophyte.","src":"p. 161, 173"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d155-pareto","points":[{"id":"d155-par-01","rank":"A","cat":"clinique","text":"**Impétigo** : S. aureus (90 %), bulle/vésicule → croûtes **mélicériques**, **péribuccal** chez l'enfant, très contagieux, sans fièvre ; chez l'adulte, souvent **impétiginisation**","src":"p. 147-148"},{"id":"d155-par-02","rank":"A","cat":"gravité","text":"Impétigo **grave** (**ecthyma**, **> 2 %** de surface, **> 6 lésions**, extension rapide) → prélèvement + ATB orale 7 j ; localisé → toilette, **mupirocine** 5 j, pas d'antiseptique, éviction **3 j**","src":"p. 147-149"},{"id":"d155-par-03","rank":"A","cat":"clinique","text":"**Furoncle** = infection profonde nécrosante du follicule pilo-sébacé (S. aureus) → **bourbillon** ; isolé : ni prélèvement ni antibiotique ; **anthrax** = conglomérat de furoncles","src":"p. 150-152"},{"id":"d155-par-04","rank":"A","cat":"gravité","text":"**Staphylococcie maligne de la face** = urgence : **manipulation** d'un furoncle (canthus interne, commissure labiale, aile du nez) → **thrombophlébite du sinus caverneux**","src":"p. 151-152"},{"id":"d155-par-05","rank":"A","cat":"étiologie","text":"**C. albicans** = saprophyte des muqueuses digestive/génitale, **jamais** de la peau saine ; favorisé par **macération**, diabète, immunodépression, **antibiotiques** → à rechercher si récidive","src":"p. 155-156, 166"},{"id":"d155-par-06","rank":"A","cat":"clinique","text":"Candidose buccale : **perlèche**, **glossite** (langue rouge dépapillée), stomatite, **muguet** (enduit blanc qui se détache au raclage) ; œsophagienne → chercher une **immunodépression**","src":"p. 156-157"},{"id":"d155-par-07","rank":"A","cat":"clinique","text":"Vulvovaginite candidosique : femme jeune ou **enceinte**, prurit, leucorrhées **« lait caillé »** ; balanite : au moindre doute, **biopsie**","src":"p. 158"},{"id":"d155-par-08","rank":"A","cat":"clinique","text":"Intertrigo **candidosique** : **bilatéral symétrique**, fond rouge **fissuré**, enduit crémeux, bordure **pustuleuse/collerette** ; onyxis : début par **péri-onyxis**","src":"p. 159, 161"},{"id":"d155-par-09","rank":"B","cat":"traitement","text":"Candidose : traiter facteurs favorisants + **tous les foyers** ; **imidazolés** locaux en 1re intention ; fluconazole si voie générale ; **aucun antifongique oral chez la femme enceinte**","src":"p. 163-164"},{"id":"d155-par-10","rank":"A","cat":"définition","text":"**Dermatophytes** = champignons filamenteux **kératinophiles** (peau, poils, ongles), **toujours pathogènes**, **respectent les muqueuses** ; anthropophiles, zoophiles ou géophiles","src":"p. 166-167"},{"id":"d155-par-11","rank":"A","cat":"clinique","text":"**Intertrigo interorteils** (3e-4e espaces, T. rubrum) = porte d'entrée de l'**érysipèle** ; kératodermie **« one hand, two feet »** (palmaire unilatérale)","src":"p. 167, 170"},{"id":"d155-par-12","rank":"A","cat":"clinique","text":"Dermatophytose cutanée : plaque annulaire, bordure active, **centrifuge**, **guérison centrale** ; pli inguinal **unilatéral**, par auto-inoculation depuis les **pieds**","src":"p. 168-169"},{"id":"d155-par-13","rank":"A","cat":"clinique","text":"**Teigne** : enfant prépubertaire, plaques alopéciques squameuses (microsporique : grande plaque unique ; trichophytique : petites plaques multiples) ; **kérion** = forme suppurée","src":"p. 171"},{"id":"d155-par-14","rank":"B","cat":"examen","text":"Mycologie des dermatophytes : **avant tout traitement**, **squames/cheveux/ongles** (pas d'écouvillon), culture **3-4 sem**, sauf intertrigo interorteils","src":"p. 173-174"},{"id":"d155-par-15","rank":"B","cat":"traitement","text":"Teigne : **local + systémique** 4-6 sem ; enfant > 10 kg : **itraconazole** 6 sem (microsporique), **terbinafine** 4 sem (trichophytique) ; ongles : traiter après identification, repousse **9-12 mois**","src":"p. 175-176"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
